<script setup>
import {ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';import Feedback from '../Components/Feedback.vue';import {crew} from '../art';
const props=defineProps({questions:Object,catalog:Object,filters:Object,bookmarks:Array});const search=ref(props.filters.search||''),subject=ref(props.filters.subject||''),saved=ref(!!props.filters.bookmarks);
function filter(){router.get('/library',{search:search.value,subject:subject.value,bookmarks:saved.value?1:0},{preserveState:true})}
</script><template><Head title="Roll Call"/><h1>Roll Call</h1><p>Explore the question library and save items for another round.</p><form class="filterbar" @submit.prevent="filter"><label>Search<input v-model="search" placeholder="Question, topic, or ID"></label><label>Subject<select v-model="subject"><option value="">All subjects</option><option v-for="s in catalog.subjects">{{s}}</option></select></label><label class="check"><input type="checkbox" v-model="saved">Bookmarks only</label><button>Find questions</button></form>
<p>{{questions.total}} matching questions</p><article v-for="q in questions.data" :key="q.id" class="panel"><div class="row"><div class="subject-line"><img class="small-portrait" :src="crew[q.subject]?.image" :alt="crew[q.subject]?.name"><div><strong>{{q.subject}}</strong><small>{{q.id}} · {{q.topic}} · {{q.tier}}</small></div></div><button class="plain" @click="router.post('/bookmarks/'+q.id,{bookmarked:!bookmarks.includes(q.id)},{preserveScroll:true})">{{bookmarks.includes(q.id)?'★ Saved':'☆ Save'}}</button></div><h2 class="pre">{{q.stem}}</h2><p v-for="(option,i) in q.options">{{String.fromCharCode(65+i)}}. {{option}}</p><details><summary>Answer and explanation</summary><Feedback :question="q"/></details></article>
<div class="row"><Link v-if="questions.prev_page_url" :href="questions.prev_page_url" class="button">Previous</Link><span>Page {{questions.current_page}} of {{questions.last_page}}</span><Link v-if="questions.next_page_url" :href="questions.next_page_url" class="button">Next</Link></div></template>
